function Badge({ children, color = "orange" }) {
  const styles = {
    orange: "bg-orange-100 text-orange-700 border-orange-200",
    cream: "bg-amber-50 text-amber-800 border-amber-200",
    blue: "bg-blue-50 text-blue-700 border-blue-200",
    green: "bg-emerald-50 text-emerald-700 border-emerald-200",
  };
  return (
    <span className={`inline-flex items-center gap-1 rounded-full border px-3 py-1 text-xs font-semibold ${styles[color]}`}>
      {children}
    </span>
  );
}

function SectionHeader({ eyebrow, title, sub }) {
  return (
    <div className="mb-10">
      <p className="text-orange-500 text-xs font-bold uppercase tracking-widest mb-2">{eyebrow}</p>
      <h2 className="text-3xl md:text-4xl font-bold text-stone-800 leading-tight">{title}</h2>
      {sub && <p className="mt-2 text-stone-500 text-base max-w-lg">{sub}</p>}
    </div>
  );
}

function BackBtn({ onClick, label = "Back" }) {
  return (
    <button onClick={onClick} className="flex items-center gap-2 text-orange-600 font-semibold text-sm hover:text-orange-700 transition-colors mb-6 group">
      <svg className="w-4 h-4 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7"/>
      </svg>
      {label}
    </button>
  );
}

function InfoCard({ icon, title, children, accent = "orange" }) {
  const border = accent === "orange" ? "border-orange-200" : accent === "green" ? "border-emerald-200" : "border-amber-200";
  const dot = accent === "orange" ? "bg-orange-400" : accent === "green" ? "bg-emerald-400" : "bg-amber-400";
  return (
    <div className={`rounded-2xl border ${border} bg-white/80 backdrop-blur-sm shadow-sm p-5`}>
      <div className="flex items-center gap-2 mb-3">
        <span className={`w-2 h-2 rounded-full ${dot}`}/>
        <h3 className="font-bold text-stone-700 text-sm uppercase tracking-wide">{icon} {title}</h3>
      </div>
      {children}
    </div>
  );
}

