function MajorLibrary({ onBack, onSelect }) {
  const [cat, setCat] = useState("All");
  const [search, setSearch] = useState("");
  const filtered = MAJORS_DATA.filter(m =>
    (cat === "All" || m.category === cat) &&
    m.name.toLowerCase().includes(search.toLowerCase())
  );

  useEffect(() => { window.scrollTo(0, 0); }, []);

  return (
    <div className="min-h-screen bg-amber-50 pt-24 pb-16 px-4">
      <div className="max-w-5xl mx-auto">
        <BackBtn onClick={onBack} label="Back to Home" />
        <SectionHeader eyebrow="Explore" title="Major Library 📚" sub="Find your field. Every major includes a full roadmap for high schoolers and beyond." />

        {/* Search */}
        <div className="relative mb-5 max-w-md">
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-4.35-4.35M17 11A6 6 0 115 11a6 6 0 0112 0z"/>
          </svg>
          <input
            className="w-full pl-10 pr-4 py-3 rounded-xl border border-orange-200 bg-white text-stone-700 placeholder-stone-400 text-sm outline-none focus:border-orange-400 transition-colors"
            placeholder="Search majors..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        {/* Category filters */}
        <div className="flex flex-wrap gap-2 mb-8">
          {CATEGORIES_MAJOR.map(c => (
            <button key={c} onClick={() => setCat(c)}
              className={`rounded-full px-4 py-1.5 text-xs font-bold border transition-all ${cat === c ? "bg-orange-500 text-white border-orange-500" : "bg-white text-stone-600 border-orange-200 hover:border-orange-400"}`}>
              {c}
            </button>
          ))}
        </div>

        {/* Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {filtered.map(m => (
            <button key={m.id} onClick={() => onSelect(m)}
              className="text-left rounded-2xl border border-orange-100 bg-white hover:shadow-lg hover:-translate-y-1 transition-all p-5 flex flex-col gap-3">
              <div className="text-3xl">{m.emoji}</div>
              <div>
                <span className="text-[10px] font-bold text-orange-400 uppercase tracking-widest">{m.category}</span>
                <h3 className="font-black text-stone-800 text-lg leading-tight" style={{ fontFamily: "'Playfair Display', serif" }}>{m.name}</h3>
              </div>
              <p className="text-stone-500 text-xs leading-relaxed line-clamp-2">{m.description}</p>
              <div className="flex flex-wrap gap-1 mt-auto">
                {m.traits.slice(0, 2).map(t => <Badge key={t}>{t}</Badge>)}
              </div>
            </button>
          ))}
        </div>

        {filtered.length === 0 && (
          <div className="text-center py-20 text-stone-400">
            <div className="text-5xl mb-3">🦆</div>
            <p className="font-semibold">No majors found. Try a different search!</p>
          </div>
        )}
      </div>
    </div>
  );
}

